<?php
if(PHP_SAPI!=='cli')exit(1);
if(!getenv('SHOP_DSN')||empty($argv[1])||!in_array('--replace',$argv,true)){fwrite(STDERR,"Set an explicit SHOP_DSN and use restore.php BACKUP_DIRECTORY --replace [--media]. Existing target data will be replaced.\n");exit(2);}
require __DIR__.'/bootstrap.php';$directory=realpath($argv[1]);if(!$directory||!is_file($directory.'/database.json')||!is_file($directory.'/SHA256')||!hash_equals(trim(file_get_contents($directory.'/SHA256')),hash_file('sha256',$directory.'/database.json')))throw new Exception('Backup checksum mismatch');
$dump=json_decode(file_get_contents($directory.'/database.json'),true,512,JSON_THROW_ON_ERROR);if(($dump['format']??0)!==1||!is_array($dump['tables']??null))throw new Exception('Invalid backup');$db=Yii::app()->db;$allowed=array_flip($db->schema->getTableNames());
foreach($dump['tables'] as $table=>$data){if(!isset($allowed[$table])||!is_array($data['rows']??null))throw new Exception('Install matching schema before restoring');$schema=$db->schema->getTable($table);foreach($data['rows'] as $row)foreach(array_keys($row) as $column)if(!isset($schema->columns[$column]))throw new Exception('Schema does not match backup');}
$sqlite=$db->driverName==='sqlite';$db->createCommand($sqlite?'PRAGMA foreign_keys=OFF':'SET FOREIGN_KEY_CHECKS=0')->execute();$tx=$db->beginTransaction();try{foreach($dump['tables'] as $table=>$data){$db->createCommand()->delete($table);foreach($data['rows'] as $row)$db->createCommand()->insert($table,$row);}if($sqlite&&$db->createCommand('PRAGMA foreign_key_check')->queryAll())throw new Exception('Foreign key check failed');if(isset($allowed['site_cache']))$db->createCommand()->delete('site_cache');if(isset($allowed['cache_versions']))Yii::app()->siteCache->invalidateAll();$tx->commit();}catch(Exception $e){if($tx->active)$tx->rollback();throw $e;}finally{$db->createCommand($sqlite?'PRAGMA foreign_keys=ON':'SET FOREIGN_KEY_CHECKS=1')->execute();}
if(in_array('--media',$argv,true)){$source=$directory.'/uploads';if(is_dir($source))foreach(new RecursiveIteratorIterator(new RecursiveDirectoryIterator($source,FilesystemIterator::SKIP_DOTS)) as $file){if($file->isLink()||!$file->isFile())continue;$relative=substr($file->getPathname(),strlen($source)+1);$target=Yii::app()->params['uploadsDir'].'/'.$relative;if(!is_dir(dirname($target)))mkdir(dirname($target),0755,true);if(!copy($file->getPathname(),$target))throw new Exception('Media restore failed');}if(is_file($directory.'/security.key')){copy($directory.'/security.key',Yii::app()->basePath.'/config/security.key');@chmod(Yii::app()->basePath.'/config/security.key',0600);}}
echo "Database restored. ".(in_array('--media',$argv,true)?'Media and encryption key restored.':'Media was not restored; preserve the matching encryption key separately.')."\n";
